-- Lot 205 : payloads 121 a 150 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_extension_payloads;
create temporary table lot_extension_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-421","moteur":"chatgpt","payload":"[RaccourcIA — /toolpath]\n\nMISSION\nVisualisez le parcours conceptuel d’un outil CNC, laser ou impression 3D sur une pièce. Créer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Quel procédé doit être représenté : CNC, laser, découpe, impression 3D ou autre ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nCréer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies. Format par défaut : 16:9, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nEXACTITUDE TECHNIQUE\nDistingue toujours données fournies, données vérifiées et représentation conceptuelle. Sans données suffisantes, privilégie un schéma pédagogique explicitement conceptuel plutôt qu’une fausse précision. N’invente ni cote, mesure, norme, performance, connexion, composant caché, diagnostic ou conformité.\n\nPRÉSERVER\nForme de pièce, axes fournis, zones d’usinage confirmées et séquence donnée.\n\nÉVITER\nG-code inventé, vitesse ou avance inventée, collision machine, promesse de fabricabilité. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique clairement que l’image n’a pas été générée.","sha256":"7693ec161034220ad8e41963ebc917f129283bb7fe0bebb6d63c1b5b27e22a17"},{"ref":"RCI-IMG-421","moteur":"claude","payload":"[RaccourcIA — /toolpath]\n\nMISSION\nVisualisez le parcours conceptuel d’un outil CNC, laser ou impression 3D sur une pièce. Créer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies.\n\nDÉCISION\nExamine d’abord toutes les images et documents, puis consolide les contraintes sans longue reformulation. Vérifie les capacités réellement disponibles avant de produire. Si le contexte suffit, exécute directement. Ne questionne jamais sur une information visible ou déjà fournie. Si un choix bloquant reste inconnu, pose UNE seule question à la fois : Quel procédé doit être représenté : CNC, laser, découpe, impression 3D ou autre ?. Réévalue après chaque réponse; « Choisis pour moi » autorise une décision professionnelle sur les préférences secondaires.\n\nEXÉCUTION\nCréer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies. Format par défaut : 16:9, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nEXACTITUDE TECHNIQUE\nDistingue toujours données fournies, données vérifiées et représentation conceptuelle. Sans données suffisantes, privilégie un schéma pédagogique explicitement conceptuel plutôt qu’une fausse précision. N’invente ni cote, mesure, norme, performance, connexion, composant caché, diagnostic ou conformité.\n\nPRÉSERVER\nForme de pièce, axes fournis, zones d’usinage confirmées et séquence donnée.\n\nÉVITER\nG-code inventé, vitesse ou avance inventée, collision machine, promesse de fabricabilité. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et directement exploitable; ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"aae2efd0779dd120114b549c68eb91e65e3182be89b64efcea60818cdf9dfc93"},{"ref":"RCI-IMG-421","moteur":"gemini","payload":"[RaccourcIA — /toolpath]\n\nMISSION\nVisualisez le parcours conceptuel d’un outil CNC, laser ou impression 3D sur une pièce. Créer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies.\n\nDÉCISION\nInspecte visuellement toutes les références avant le texte de contexte et attribue à chacune son rôle : sujet, style, données ou composition. Si les éléments indispensables sont présents, génère immédiatement. Ne redemande jamais ce qui est visible ou déjà connu. Si une décision critique manque, pose UNE seule question à la fois : Quel procédé doit être représenté : CNC, laser, découpe, impression 3D ou autre ?. Après la réponse, exécute dès que le contexte devient suffisant; « Choisis pour moi » permet de décider les préférences créatives secondaires.\n\nEXÉCUTION\nCréer une visualisation pédagogique des trajectoires et étapes, clairement distincte d’un programme machine exécutable sauf si des données certifiées sont fournies. Format par défaut : 16:9, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nEXACTITUDE TECHNIQUE\nDistingue toujours données fournies, données vérifiées et représentation conceptuelle. Sans données suffisantes, privilégie un schéma pédagogique explicitement conceptuel plutôt qu’une fausse précision. N’invente ni cote, mesure, norme, performance, connexion, composant caché, diagnostic ou conformité.\n\nPRÉSERVER\nForme de pièce, axes fournis, zones d’usinage confirmées et séquence donnée.\n\nÉVITER\nG-code inventé, vitesse ou avance inventée, collision machine, promesse de fabricabilité. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"8e8c2f0c0220e9dfe0a33dee430d8fa6ab00514c08738baf2e8846cf1f4b6bc1"},{"ref":"RCI-IMG-422","moteur":"chatgpt","payload":"[RaccourcIA — /weldmap]\n\nMISSION\nRepérez les zones et types de soudure sur une pièce ou assemblage à partir des informations fournies. Surligner les joints confirmés, utiliser les symboles fournis et séparer nettement annotation pédagogique et instruction de production validée.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Quels joints ou symboles de soudure sont déjà définis dans vos données ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nSurligner les joints confirmés, utiliser les symboles fournis et séparer nettement annotation pédagogique et instruction de production validée. Format par défaut : 16:9, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nEXACTITUDE TECHNIQUE\nDistingue toujours données fournies, données vérifiées et représentation conceptuelle. Sans données suffisantes, privilégie un schéma pédagogique explicitement conceptuel plutôt qu’une fausse précision. N’invente ni cote, mesure, norme, performance, connexion, composant caché, diagnostic ou conformité.\n\nPRÉSERVER\nGéométrie, numéros de pièces, symboles et séquence fournis.\n\nÉVITER\nType de soudure inventé, dimension de cordon déduite, conformité normative affirmée sans source. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique clairement que l’image n’a pas été générée.","sha256":"8532306da590716112967ac86f01d5bc3ac7d7d053e66635e3f53762b37dda83"},{"ref":"RCI-IMG-422","moteur":"claude","payload":"[RaccourcIA — /weldmap]\n\nMISSION\nRepérez les zones et types 